-- Nassau Academy English — Round 7a: AI voice audio (ElevenLabs)
-- Every line to record lives in audio_lines; the tts edge function generates the MP3s into the public "audio" bucket.

on conflict (id) do update set public = true;

create table if not exists public.audio_lines (
  id text primary key,                 -- E01-05 (episode line) or M1-L3-S1 (exercise clip)
  kind text not null check (kind in ('episode','exercise')),
  episode int,
  module int not null,
  step_id uuid references public.steps(id) on delete set null,
  lines jsonb not null,                -- [{speaker, text, say}] — say = text sent to the voice
  url text,
  chars int,
  generated_at timestamptz,
  updated_at timestamptz not null default now()
);
alter table public.audio_lines enable row level security;
drop policy if exists "audio_lines: staff read" on public.audio_lines;
create policy "audio_lines: staff read" on public.audio_lines for select to authenticated using (public.is_staff());
drop policy if exists "audio_lines: admin edit" on public.audio_lines;
create policy "audio_lines: admin edit" on public.audio_lines for update to authenticated using (public.is_admin()) with check (public.is_admin());

-- Voice settings (voice IDs are filled in by the admin in Admin → Audio)
  'model', 'eleven_multilingual_v2',
  'format', 'mp3_44100_192',
  'speed', jsonb_build_object('1', 0.9, '2', 0.95, '3', 1.0, '4', 1.0),
  'voices', '{}'::jsonb))
on conflict (key) do nothing;

create or replace function public.step_at(m int, l int, p int) returns uuid language sql stable set search_path = public as $$
  select s.id from steps s join lessons le on le.id = s.lesson_id join modules mo on mo.id = le.module_id
  join courses c on c.id = mo.course_id where c.code = 'en-a1-1' and mo.position = m and le.position = l and s.position = p;
$$;
revoke execute on function public.step_at(int,int,int) from public, anon, authenticated;

on conflict (id) do update set lines = excluded.lines, step_id = excluded.step_id, module = excluded.module, updated_at = now();
